from hypothesis import given, strategies as st
from solution import merge_sorted


def test_merge_examples():
    assert merge_sorted([1, 3, 5], [2, 4]) == [1, 2, 3, 4, 5]
    assert merge_sorted([], [1]) == [1]
    assert merge_sorted([], []) == []


@given(st.lists(st.integers()), st.lists(st.integers()))
def test_merge_sorted_property(a, b):
    result = merge_sorted(sorted(a), sorted(b))
    assert result == sorted(a + b)

from solution import word_count


def test_w():
    assert word_count('The cat, the hat!') == {'the': 2, 'cat': 1, 'hat': 1}
    assert word_count('') == {}

from solution import invert_dict


def test_i():
    assert invert_dict({'a': 1, 'b': 2}) == {1: 'a', 2: 'b'}
    assert invert_dict({}) == {}

from solution import merge_dicts_sum


def test_m():
    assert merge_dicts_sum({'x': 1}, {'x': 2, 'y': 5}) == {'x': 3, 'y': 5}
    assert merge_dicts_sum({}, {}) == {}

from solution import group_by_length


def test_g():
    assert group_by_length(['a', 'bb', 'cc', 'ddd']) == {1: ['a'], 2: ['bb', 'cc'], 3: ['ddd']}
    assert group_by_length([]) == {}

from solution import char_frequency


def test_c():
    assert char_frequency('aab') == {'a': 2, 'b': 1}
    assert char_frequency('') == {}

from solution import zip_dict


def test_z():
    assert zip_dict(['a', 'b'], [1, 2, 3]) == {'a': 1, 'b': 2}
    assert zip_dict([], [1]) == {}

from solution import all_subsets


def test_s():
    got = {tuple(sorted(x)) for x in all_subsets([1, 2])}
    assert got == {(), (1,), (2,), (1, 2)}
    assert all_subsets([]) == [[]]
